contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketAmount, uint feeAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketAmount)); require(ticketAmount <= 1000000000000000000000000000000);
        require(ticketAmount == 10);
        require(feeAmount == 1);
        require(address(this).balance >= ticketAmount);
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        c.play{value: ticketAmount}(); if (__ESBMC_reverted()) return;
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;
        assert(afterPot == 0 || afterPot == beforePot + ticketAmount);
    }

    receive() external payable {}
}

