pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketAmount, uint256 feeAmount) internal {
        ticketAmount = bound(ticketAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketAmount = 10;
        feeAmount = 1;
        vm.assume(address(this).balance >= ticketAmount);
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.play{value: ticketAmount}() {} catch { return; }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterPot == 0 || afterPot == beforePot + ticketAmount);
    }

    function testFuzz_run(uint256 ticketAmount, uint256 feeAmount) public {
        _run(ticketAmount, feeAmount);
    }

    receive() external payable {}
}
